// Bilingual, source-linked rules. Conditions are evaluated against the saved mission.
export const L=(pt,en)=>({pt,en});
export const maps=[
{id:'launch',name:'Launch Facility',box:'core',page:14,art:'map-launch',desc:L('Pátios abertos, prédios e terreno difícil. Recomendado para a primeira partida.','Open yards, buildings and difficult terrain. Recommended for a first game.')},
{id:'pens',name:'Submarine Pens',box:'core',page:14,art:'map-pens',desc:L('Passarelas elevadas, túneis e linhas de tiro sobre a água.','Elevated walkways, tunnels and firing lines across water.')},
{id:'water',name:'Heavy Water',box:'eagle',page:4,art:'map-water',desc:L('Penhascos, barragem e grandes áreas abertas.','Cliffs, a dam and wide open areas.')},
{id:'nest',name:'Eagle’s Nest',box:'eagle',page:6,art:'map-nest',desc:L('Corredores estreitos, portas e paredes reforçadas.','Narrow corridors, doorways and reinforced walls.')},
{id:'village',name:'Norman Village',box:'kraken',page:4,art:'map-village',desc:L('Ruínas, várias entradas e dois carros blindados.','Ruins, multiple entrances and two armoured cars.')},
{id:'carrier',name:'Super Carrier',box:'kraken',page:6,art:'map-carrier',desc:L('Três conveses, portas trancáveis e dutos de ar.','Three decks, lockable doors and air ducts.')}
];
export const books={core:{name:'Sniper Elite',pages:16},eagle:{name:'Eagle’s Nest',pages:8},escalation:{name:'Escalation',pages:20},kraken:{name:'Operation Kraken',pages:8}};
export const snipers={base:{name:'Karl · '+ 'Base',bag:[6,2,3]},roza:{name:'Roza',bag:[4,1,2]},jun:{name:'Jun',bag:[6,2,2]},karl:{name:'Karl · M1903',bag:[7,2,1]},eazy:{name:'Major Eazy',bag:[3,3,3]},ghost:{name:'Ghost Sniper',bag:null}};
export const advantages=[{id:'schedule',name:'Accelerated Schedule',map:'any'},{id:'rapid',name:'Rapid Response',map:'pens'},{id:'tipped',name:'Tipped Off',map:'carrier'},{id:'roadblocks',name:'Roadblocks',map:'launch'},{id:'mechanisation',name:'Mechanisation',map:'water',requires:'kraken'},{id:'curfew',name:'Under Curfew',map:'village'},{id:'sentries',name:'Sentries',map:'nest'}];
export const defaults={lang:'pt',map:'launch',expansions:[],allied:'base',eagleLoadout:true,rank:1,sniperEdges:[],defenderEdges:[],upgrades:0,extras:0,elites:0,role:'sniper',checks:[]};
export function normalize(raw={}){const s={...defaults,...raw};s.lang=['pt','en'].includes(s.lang)?s.lang:'pt';s.expansions=Array.isArray(s.expansions)?s.expansions.filter(x=>['eagle','escalation','kraken'].includes(x)):[];if(!maps.some(m=>m.id===s.map&&(m.box==='core'||s.expansions.includes(m.box))))s.map='launch';s.role=s.role==='defender'?'defender':'sniper';s.rank=[1,2,3].includes(+s.rank)?+s.rank:1;s.allied=s.expansions.includes('eagle')&&snipers[s.allied]?s.allied:'base';s.eagleLoadout=!!s.eagleLoadout;s.sniperEdges=Array.isArray(s.sniperEdges)?[...new Set(s.sniperEdges.filter(x=>['killshot','goodboy'].includes(x)))]:[];s.defenderEdges=Array.isArray(s.defenderEdges)?[...new Set(s.defenderEdges.filter(x=>['flares','hunter'].includes(x)||advantages.some(a=>a.id===x&&(a.map==='any'||a.map===s.map)&&(!a.requires||s.expansions.includes(a.requires)))))]:[];for(const k of ['upgrades','extras','elites'])s[k]=Math.max(0,Math.min(s.rank,Math.floor(Number(s[k])||0)));if(!s.expansions.includes('escalation')){s.sniperEdges=[];s.defenderEdges=[];s.upgrades=s.extras=s.elites=0;}s.sniperEdges=s.sniperEdges.slice(0,s.rank);s.upgrades=Math.min(s.upgrades,s.rank-s.sniperEdges.length);s.extras=Math.min(s.extras,s.rank-s.sniperEdges.length-s.upgrades);s.defenderEdges=s.defenderEdges.slice(0,s.rank);s.elites=Math.min(s.elites,s.rank-s.defenderEdges.length);s.checks=Array.isArray(s.checks)?s.checks.filter(x=>typeof x==='string'):[];return s;}
export const edge=(s,id)=>s.sniperEdges.includes(id)||s.defenderEdges.includes(id);
export const vehicles=s=>s.map==='village'||edge(s,'mechanisation');
export const doors=s=>s.map==='carrier'||edge(s,'curfew');
export const limit=s=>edge(s,'schedule')?7:10;
export function applies(r,s){if(r.when&&!r.when(s))return false;return true;}
const R=(id,section,role,title,body,book,page,when)=>({id,section,role,title,body,book,page,when});
export const rules=[
R('sniper-turn','turns','sniper',L('Seu turno, na ordem que você escolher','Your turn, in your chosen order'),L('Retire sua miniatura do tabuleiro no início do turno. Você pode fazer um movimento.\nVocê pode usar 1 carta de equipamento.\nVocê pode realizar 1 ação adicional: atirar, saquear ou completar um objetivo. A ordem é livre, mas não interrompa um movimento ou ação para fazer outra coisa. Pode passar qualquer etapa; isso não concede ações extras. No primeiro turno, a primeira ação deve ser entrar no tabuleiro pela seta escolhida. Ao terminar, registre o número da contagem regressiva na sua posição no tabuleiro oculto.','Remove your miniature at the start of your turn. You may make one movement.\nYou may use 1 loadout card.\nYou may take 1 additional action: shoot, loot or complete an objective. Choose the order, but do not interrupt movement or an action with something else. You may skip any part; this grants no extra actions. Your very first action must be moving onto the board from your chosen arrow. At the end, record the countdown number in your space on the hidden board.'),'core',5),
R('movement','turns','sniper',L('Movimento e ruído','Movement and noise'),L('Mova 0–3 espaços. Com 0–1, não alerte os defensores pelo movimento. Com 2–3, anuncie todos os defensores adjacentes a qualquer espaço do percurso, incluindo início e fim, somente após mover. Não revele a ordem nem a quantidade de espaços ouvidos. Paredes e elevação não impedem o ruído. Não entre em um espaço com defensor, não retorne a um espaço já ocupado neste turno e use portas/escadas para entrar ou sair de áreas fechadas/elevadas. Se um defensor entrou no seu espaço no turno dele, você não precisa se revelar e pode sair normalmente.','Move 0–3 spaces. Moving 0–1 does not alert defenders through movement. Moving 2–3 alerts every defender adjacent to any space on your route, including start and finish, after movement ends. Do not disclose the order or number of spaces heard. Walls and elevation do not block noise. Do not enter a defender’s space, revisit a space occupied this turn, or enter/leave enclosed or elevated areas except through access points. If a defender entered your space on their turn, remain hidden and leave normally.'),'core',5),
R('shoot','turns','sniper',L('Atirar: escolha, anuncie, compre e resolva','Shoot: choose, announce, draw and resolve'),L('Escolha secretamente um alvo com linha de visão. Conte o menor número de espaços atravessados em uma linha reta válida, incluindo o alvo, excluindo sua posição (mínimo 1, mesmo no mesmo espaço). Anuncie quantas fichas comprará antes de comprar e mostre todas. Precisa de pelo menos essa quantidade de Mira para acertar. 5 ou mais fichas de Recuo + Ruído causam falha, independentemente da Mira. Com 2 ou mais Ruídos não suprimidos, revele sua posição; cada Supressão aumenta esse limite em 1, mas não reduz a soma usada para falha. Acerto remove a unidade. Devolva todas as fichas compradas ao saco. Se mover depois, deixe a miniatura na última posição revelada.','Secretly choose a target in line of sight. Count the fewest spaces crossed by a valid straight line, including the target but excluding your space (minimum 1, even in the same space). Announce how many tokens you will draw before drawing, then show them all. You need at least that many Aim tokens to hit. 5 or more Recoil + Noise tokens cause a misfire regardless of Aim. With 2 or more unsuppressed Noise, reveal your position; each Suppression raises that threshold by 1, but does not reduce the misfire total. A hit removes the unit. Return all drawn tokens to the bag. If you move afterward, leave the miniature at the last revealed position.'),'core',6),
R('bag','turns','sniper',L('Alterações no saco de tiro','Changes to the shot bag'),L('Soldado morto: +1 Mira. Oficial morto: adicione a Supressão da carta dele; se já foi retirada, +1 Mira. Objetivo concluído ou sniper encontrado por Observar: +1 Ruído. Limites da caixa: 11 Mira, 9 Ruído, 3 Supressão; se acabar uma ficha, apenas ignore a adição. As 3 fichas de Recuo iniciais não aumentam pelas regras básicas.','Killed soldier: +1 Aim. Killed officer: add the Suppression from their specialist card; if already taken, +1 Aim instead. Completed objective or successful Spot: +1 Noise. Supply limits: 11 Aim, 9 Noise, 3 Suppression; skip an addition when that supply runs out. The 3 initial Recoil tokens do not increase under the base rules.'),'core',6),
R('loot','turns','sniper',L('Saquear','Loot'),L('Esteja em um espaço de objetivo que não corresponda às suas cartas. Compre 3 equipamentos, guarde 1 e devolva os outros, embaralhando o baralho. Marque o local no tabuleiro oculto: cada local só pode ser saqueado uma vez. Os defensores sabem que você está em um objetivo, mas não qual.','Be on an objective space that does not match your objective cards. Draw 3 loadout cards, keep 1 and shuffle the others back into the deck. Mark the location on your hidden board: each location may be looted only once. Defenders know you are on an objective, but not which one.'),'core',7),
R('objective','turns','sniper',L('Completar um objetivo','Complete an objective'),L('No espaço correspondente, revele a carta como sua ação adicional. Coloque a miniatura ali, adicione 1 Ruído e reinicie os cubos de contagem em 10 (7 com Accelerated Schedule). O segundo objetivo concluído dá vitória imediata. Você pode completar seus dois objetivos em qualquer ordem.','On the matching space, reveal the card as your additional action. Place your miniature there, add 1 Noise and reset the countdown cubes to 10 (7 with Accelerated Schedule). Your second completed objective wins immediately. You may complete your objectives in either order.'),'core',7),
R('loadout','turns','sniper',L('Usar equipamento','Use loadout'),L('Uma carta por turno, normalmente de uso único. Anuncie que vai usar, coloque virada para baixo e revele no momento indicado: antes de usar/atirar, quando ativada ou ao fim da partida. Se modifica uma ação, jogue antes dela. Nunca no meio de movimento/ação. As cartas têm precedência nas exceções, como Bayonet.','One card per turn, normally single use. Announce its use, place it face down and reveal at the printed time: before using/shooting, when triggered or at game end. Play cards affecting an action before that action. Never interrupt movement or an action. Explicit card exceptions, such as Bayonet, apply.'),'core',7),
R('defender-turn','turns','defender',L('Três esquadrões, duas ações por esquadrão','Three squads, two actions each'),L('Cada esquadrão escolhe uma opção:\nColetar informações: gaste as duas ações.\nOU executar 2 ações de unidades.\nDistribua essas ações entre as unidades do esquadrão.\nUma unidade pode fazer 2 ações diferentes. Uma unidade não pode repetir a mesma ação no turno. Esquadrões podem intercalar ações. Mova um cubo para a próxima casa da contagem por ação; para passar, também avance o cubo. Informações usam os dois cubos. Todos avançam apenas uma casa por rodada, não seis casas. Habilidades de especialistas são adicionais, salvo quando modificam uma ação.','Each squad chooses one option:\nGather intel: spend both actions.\nOR take 2 unit actions.\nDistribute those actions among the squad’s units.\nOne unit may take 2 different actions. A unit cannot repeat the same action in a turn. Squads may interleave their actions. Move one cube to the next countdown space per action; also advance it when passing. Intel spends both cubes. All cubes advance one space per round, not six spaces. Specialist abilities are additional, except when they modify a unit action.'),'core',8),
R('intel','turns','defender',L('Coletar informações','Gather intel'),L('O oficial deve estar no próprio setor. Gaste as duas ações do esquadrão e declare o setor. O sniper responde se está ou não nele, sem indicar posição. Isso substitui as ações de unidades desse esquadrão, mas não impede sua habilidade de especialista.','The officer must be in their own sector. Spend both squad actions and name that sector. The sniper states whether they are in it, without identifying their space. This replaces that squad’s unit actions, but does not prevent its specialist ability.'),'core',8),
R('defender-move','turns','defender',L('Mover até 2 espaços','Move up to 2 spaces'),L('Pode passar por defensores, mas não terminar no espaço de outro defensor. Pode entrar no espaço do sniper sem descobri-lo automaticamente. Respeite portas, escadas e terreno difícil.','You may pass through defenders, but may not end in another defender’s space. You may enter the sniper’s space without automatically discovering them. Respect doors, ladders and difficult terrain.'),'core',8),
R('attack','turns','defender',L('Atacar','Attack'),L('Ataque o espaço da própria unidade. Se o sniper estiver lá, ele coloca a miniatura e recebe 1 ferimento. Vire o marcador; o segundo ferimento vence a partida imediatamente. Só entrar no espaço não é um ataque.','Attack the unit’s own space. If the sniper is there, they place their miniature and take 1 wound. Flip the wound token; a second wound wins immediately. Simply entering the space is not an attack.'),'core',8),
R('spot','turns','defender',L('Observar (Spot)','Spot'),L('Escolha 1 espaço adjacente. Se o sniper estiver nele, revele sua posição com a miniatura e adicione 1 Ruído ao saco. Pode observar entre tipos diferentes de espaço. Respeite as exceções de paredes reforçadas e portas trancadas do mapa.','Choose 1 adjacent space. If the sniper is there, reveal their position with the miniature and add 1 Noise to the bag. You may spot between different space types. Respect the map’s reinforced-wall and locked-door exceptions.'),'core',9),
R('sweep','turns','defender',L('Varrer (Sweep)','Sweep'),L('Verifique o espaço da unidade e 2 espaços adjacentes do mesmo tipo (aberto, fechado ou elevado). O sniper responde apenas se está em algum dos três: não revela qual e não adiciona Ruído. Adjacência compatível exige uma borda em comum e o mesmo tipo de espaço.','Check the unit’s space and 2 matching-adjacent spaces (same type: open, enclosed or elevated). The sniper only says whether they are in any of those three: no exact position and no Noise added. Matching-adjacent means sharing an edge and having the same space type.'),'core',9),
R('deploy','turns','defender',L('Recolocar ou dispensar unidades','Deploy or dismiss units'),L('Oficial fora do tabuleiro: recoloque no início da sua cor; libere o espaço antes se outro defensor estiver nele. Soldado fora: com o oficial no próprio setor, coloque o soldado em espaço adjacente do mesmo tipo, até em outro setor. A ação conta para o soldado, que ainda pode fazer outra ação diferente. Dispensar retira uma unidade do esquadrão; ela não pode ser recolocada no mesmo turno.','Officer off the board: return them to their colour’s starting space; clear it first if occupied by another defender. Soldier off the board: with their officer in their own sector, place the soldier in a matching-adjacent space, even across a sector border. This counts as the soldier’s action; they may still take a different action. Dismiss removes a squad unit; it cannot redeploy that turn.'),'core',9),
R('specialists','turns','defender',L('Especialistas','Specialists'),L('Cada oficial tem uma habilidade com 2 usos por partida e no máximo 1 uso por turno. Remova um cubo da carta ao usar. O oficial precisa estar no tabuleiro, mas não no próprio setor. Anuncie habilidades que modificam ações antes da ação; elas não concedem uma ação extra. “Soldado” exclui oficiais. O Medic pode reagir no turno do sniper, limitado a 1 uso por turno; se também for atingido pela Trench Gun, não pode proteger outro alvo. As habilidades completas dos seis especialistas básicos estão nas cartas físicas (não reproduzidas integralmente no manual anexado).','Each officer has an ability with 2 uses per game and at most 1 use per turn. Remove a cube from the card when used. The officer must be on the board, but need not be in their own sector. Announce action-modifying abilities before the action; they do not grant an extra action. “Soldier” excludes officers. The Medic can react on the sniper’s turn, at most once that turn; if also hit by the Trench Gun, he cannot protect another target. Full abilities of the six base specialists are on their physical cards (not fully reproduced in the attached rulebook).'),'core',9),
R('los','turns','both',L('Linha de visão','Line of sight'),L('Trace uma reta de qualquer borda do seu espaço até qualquer borda do alvo. Não atravesse um espaço fechado, elevado ou uma obstrução. Pode atirar para dentro/fora de um espaço fechado ou elevado: começar ou terminar nele não é atravessá-lo. Dentro do mesmo prédio, pode atravessar espaços fechados se toda a linha ficar em espaços fechados. Entre dois espaços elevados, pode passar sobre espaços abertos/fechados, contando-os na distância; obstruções continuam bloqueando. Paredes comuns não bloqueiam tiros (há janelas), mas não permitem movimento.','Trace a straight line from any edge of your space to any edge of the target. Do not pass through enclosed/elevated spaces or obstructions. You may shoot into/out of an enclosed or elevated space: starting or ending there is not passing through it. Within the same building, you may trace through enclosed spaces if the whole line stays enclosed. Between elevated spaces, you may shoot over open/enclosed spaces, counting them toward distance; obstructions still block. Ordinary walls do not block shots (there are windows), but do block movement.'),'core',12),
R('terrain','turns','both',L('Terreno, setores e adjacência','Terrain, sectors and adjacency'),L('Cada mapa tem setores amarelo, vermelho, preto e branco neutro. Adjacentes compartilham borda; adjacentes do mesmo tipo também compartilham a classificação aberto/fechado/elevado. Terreno difícil reduz o máximo de movimento em 1: sniper até 2; defensor até 1. Não entre nele como terceiro/segundo passo, respectivamente. Água não permite entrada, mas não bloqueia visão; obstrução impede ambos. Portas e escadas são acessos obrigatórios.','Maps have yellow, red, black and neutral white sectors. Adjacent spaces share an edge; matching-adjacent spaces also share the open/enclosed/elevated type. Difficult terrain reduces maximum movement by 1: sniper up to 2; defender up to 1. Do not enter it as your third/second step respectively. Water cannot be entered, but does not block sight; obstructions block both. Doorways and ladders are required access points.'),'core',10),
R('pens-map','turns','both',L('Submarine Pens: túneis e passarelas','Submarine Pens: tunnels and walkways'),L('Passarelas claras são elevadas; salas nos setores amarelo, preto e vermelho são fechadas. Os dois espaços vermelhos sob a passarela são túneis separados dos espaços acima: não são adjacentes e não têm visão entre si. Salas ao lado das passarelas não têm visão direta delas: a linha entre fechado e elevado deve atravessar ao menos 1 espaço aberto ou uma escada.','Light walkways are elevated; rooms in yellow, black and red sectors are enclosed. The two red spaces under the walkway are tunnels distinct from the spaces above: no adjacency or line of sight between them. Rooms beside walkways do not have direct sight to them: sight between enclosed and elevated must cross at least 1 open space or a ladder.'),'core',14,s=>s.map==='pens'),
R('launch-map','turns','both',L('Launch Facility: leitura do mapa','Launch Facility: reading the map'),L('Prédios, submarino e os três vagões no setor preto são fechados. Entre e saia pelas portas. Terreno difícil continua sendo espaço aberto e compatível com os abertos ao redor. Não há espaços elevados nem obstruções.','Buildings, submarine and the three rail cars in the black sector are enclosed. Enter and exit through doors. Difficult terrain remains open and matching-adjacent to surrounding open spaces. There are no elevated spaces or obstructions.'),'core',14,s=>s.map==='launch'),
R('water-map','turns','both',L('Heavy Water: barragem e penhascos','Heavy Water: dam and cliffs'),L('Topo da barragem e penhascos acima/à direita são elevados; use os caminhos marcados. Cada prédio é um único espaço fechado. Só é possível entrar em 1 espaço de terreno difícil por turno; a rota na base da barragem é lenta.','Dam top and cliffs along the top/right are elevated; use the marked paths. Each building is a single enclosed space. You can enter only 1 difficult terrain space per turn; the route at the foot of the dam is slow.'),'eagle',4,s=>s.map==='water'),
R('nest-map','turns','both',L('Eagle’s Nest: paredes reforçadas','Eagle’s Nest: reinforced walls'),L('Não atire nem observe através das paredes reforçadas; ruído atravessa. Cada sala é uma área fechada distinta; corredores de mármore, varanda esquerda e corredor de serviço acima/à direita são abertos. Ao ver uma porta, pode mirar no espaço imediatamente do outro lado, não além. Se houver porta no seu espaço, trace visão como se estivesse do outro lado dela. Pode atravessar duas portas somente começando junto à primeira e terminando logo após a segunda.','You cannot shoot or spot through reinforced walls; noise passes through. Each room is a separate enclosed area; marble corridors, left balcony and top/right servants’ corridor are open. Seeing a doorway lets you target the space immediately beyond, no further. If your space has a doorway, trace sight as if standing just beyond it. Shooting through two doors requires starting at the first and ending immediately beyond the second.'),'eagle',6,s=>s.map==='nest'),
R('vehicle','turns','both',L('Veículos: embarcar, dirigir e atacar','Vehicles: embark, drive and attack'),L('Veículos só circulam em espaços com ícone de estrada/início de veículo. Terminar um movimento em um veículo vazio obriga a embarcar; coloque a unidade na carta. Um passageiro por veículo. Para sair, faça Mover: comece no espaço do veículo e termine em outro, até 2 espaços. Passageiros mantêm ações normais e ganham: Dirigir 3; Dirigir até 1 + Varrer; Dirigir até 1 + Observar; Atacar um espaço adjacente. São ações diferentes e podem ser combinadas, respeitando 2 ações por esquadrão e sem repetir a mesma ação na unidade. Veículos passam por unidades/veículos, mas não terminam sobre eles. Sniper pode entrar no espaço de veículo vazio; ocupado bloqueia e ouve ruído como uma unidade.','Vehicles travel only on spaces with road/vehicle-start icons. Ending a move in an empty vehicle forces embarkation; put the unit on its card. One passenger per vehicle. Disembark with Move: start in the vehicle’s space and finish elsewhere, up to 2 spaces away. Passengers retain normal actions and gain: Drive 3; Drive up to 1 & Sweep; Drive up to 1 & Spot; Attack an adjacent space. These are distinct actions and may be combined, respecting the squad’s 2-action budget and no repeats by one unit. Vehicles pass through units/vehicles but cannot end on them. Snipers may enter empty vehicle spaces; occupied vehicles block and hear noise like units.'),'kraken',4,vehicles),
R('armour','turns','both',L('Blindagem 2 e destruição de veículos','Armour 2 and vehicle destruction'),L('Para acertar um veículo, obtenha 2 Miras além da distância normal: mínimo 3 mesmo no mesmo espaço. Destrua o veículo e mate o passageiro, se houver; adicione apenas a recompensa pelo passageiro (Mira/Supressão). O veículo não volta à partida. Efeitos que matam diretamente (Knife, S-Mine, Trench Gun) não afetam veículo nem passageiro. Distração pode forçar um passageiro a desembarcar como parte do movimento, mas não move o veículo.','Hitting a vehicle requires 2 Aim beyond the normal distance: minimum 3 even in the same space. Destroy it and kill any passenger; only add the passenger’s normal Aim/Suppression reward. The vehicle never returns. Direct-kill effects (Knife, S-Mine, Trench Gun) do not affect vehicles or passengers. Distraction may force a passenger to disembark as part of movement, but cannot move the vehicle.'),'kraken',4,vehicles),
R('village-map','turns','both',L('Norman Village: múltiplas entradas','Norman Village: multiple entrances'),L('Três setores têm duas setas de entrada. Escolha qualquer entrada de um setor que não contenha seus objetivos. Os dois blindados começam nos símbolos de início de veículo.','Three sectors have two entry arrows. Choose any entrance in a sector containing neither objective. The two armoured cars start at the vehicle-start icons.'),'kraken',5,s=>s.map==='village'),
R('doors','turns','both',L('Portas trancadas','Locked doors'),L('Portas começam abertas e pertencem aos dois espaços que sobrepõem. Trancadas impedem movimento e linha de visão para/através do espaço do outro lado. Defensor no espaço da porta pode trancar/destrancar como parte de Mover, gastando 1 dos 2 passos, antes ou depois de mover. Sniper pode atirar em porta aberta ou trancada: acerto remove a ficha permanentemente, sem adicionar fichas ao saco.','Doors start unlocked and belong to both spaces they overlap. Locked doors block movement and line of sight into/through the space beyond. A defender in a door’s space may lock/unlock as part of Move, spending 1 of the 2 movement steps, before or after moving. The sniper may shoot an open or locked door: a hit permanently removes the token, without adding tokens to the bag.'),'kraken',6,doors),
R('carrier-map','turns','both',L('Super Carrier: níveis, escadas e dutos','Super Carrier: levels, ladders and ducts'),L('Há três níveis; não saia do navio. Escadas com letras iguais conectam espaços para movimento, ruído, Observar e visão, mas não são adjacentes do mesmo tipo para Varrer. Dutos com letras iguais conectam apenas para movimento e visão do sniper, não ruído; não dão adjacência aos defensores. Não há visão para outros espaços de outro nível. Há uma única entrada, sempre usada. Objetivos devem ter naipes diferentes e também valores diferentes; figuras correspondem ao símbolo e naipe do espaço.','There are three levels; do not leave the ship. Matching-letter ladders connect spaces for movement, noise, Spot and sight, but are not matching-adjacent for Sweep. Matching-letter ducts connect only for sniper movement and sight, not noise; they give defenders no adjacency. There is no sight to other spaces on another level. Always use the single entrance. Objectives must differ in both suit and value; face-card objectives match the space’s symbol and suit.'),'kraken',6,s=>s.map==='carrier'),
R('carrier-intel','turns','defender',L('Informações por nível ou setor','Intel by level or sector'),L('Declare setor ou nível ao coletar informações. Para nível, o oficial deve estar nele, mas pode estar em qualquer setor. O sniper responde se está no mesmo nível. No mesmo turno, os defensores podem investigar vários setores OU vários níveis, nunca misturar os dois tipos.','Declare sector or level when gathering intel. For level intel, the officer must be on that level but may be in any sector. The sniper states whether they share that level. During the same turn, defenders may investigate multiple sectors OR multiple levels, never a mix of both.'),'kraken',6,s=>s.map==='carrier'),
R('carrier-walls','turns','both',L('Super Carrier: paredes e visão','Super Carrier: walls and sight'),L('Paredes reforçadas bloqueiam ações/efeitos, incluindo Observar, Varrer, Jager e Panzerfaust; ruído ainda atravessa. Pode mirar logo após uma porta destrancada, não além. Com porta no próprio espaço, espie como se estivesse do outro lado; duas portas só se começar junto à primeira e terminar após a segunda. Ponte, área de oficiais e duas salas de máquinas são fechadas; as demais áreas são abertas, mesmo separadas por portas.','Reinforced walls block actions/effects, including Spot, Sweep, Jager and Panzerfaust; noise still passes through. Target immediately beyond an unlocked doorway, no further. With a doorway in your own space, peek as if beyond it; two-door shots require starting at the first and ending beyond the second. The bridge, officer area and two engine rooms are enclosed; other areas are open, even when separated by doors.'),'kraken',7,s=>s.map==='carrier'),
R('allies','turns','sniper',L('Snipers aliados','Allied snipers'),L('Roza (4 Mira / 1 Ruído / 2 Recuo): no máximo 5 fichas por tiro. Jun (6/2/2): acerto também remove unidades adjacentes do mesmo tipo ao alvo; cada baixa adicional adiciona Ruído em vez de Mira/Supressão, sem exigir visão até ela. Karl M1903 (7/2/1): pode atirar duas vezes em vez de mover; todo tiro contra alvo a até 2 espaços adiciona Ruído depois. Tommy/Trench substitui um desses tiros. Major Eazy (3/3/3): Ruído também conta como Mira, mas ainda revela e conta para falha. Efeitos são obrigatórios, exceto a escolha dos dois tiros de Karl.','Roza (4 Aim / 1 Noise / 2 Recoil): draw at most 5 tokens per shot. Jun (6/2/2): a successful shot also removes units matching-adjacent to the target; each extra kill adds Noise instead of Aim/Suppression, with no sight required to it. Karl M1903 (7/2/1): may shoot twice instead of moving; every shot at a target within 2 spaces adds Noise afterward. Tommy/Trench replaces one of those shots. Major Eazy (3/3/3): Noise also counts as Aim, but still reveals and counts toward misfire. Effects are mandatory except Karl’s choice to shoot twice.'),'eagle',3,s=>s.allied!=='base'),
R('ghost','turns','both',L('Ghost Sniper: identidade oculta','Ghost Sniper: hidden identity'),L('Sorteie um aliado e prepare carta, saco e reserva em segredo. Não selecione a identidade secreta neste dispositivo compartilhado. Revele a carta quando usar sua habilidade, tiver posição revelada, completar objetivo ou for encontrado por Observar/Atacar. Pegue então a miniatura correspondente.','Randomly draw an ally and prepare card, bag and supply secretly. Do not select the hidden identity on this shared device. Reveal the card when using its ability, revealing your position, completing an objective or being found by Spot/Attack. Then take the matching miniature.'),'eagle',8,s=>s.allied==='ghost'),
R('killshot','turns','sniper',L('Killshot: alvo secundário','Killshot: secondary target'),L('Ao atirar, pode escolher como alvo secundário um defensor sem blindagem em um espaço atravessado pela linha até o alvo principal. Se acertar com 0–1 Recuo, remova ambos e receba fichas por ambos. Com 2+ Recuos, pode remover o secundário em vez do principal, recebendo só a ficha dele.','When shooting, you may choose an unarmoured defender in a space crossed by the line to the primary target as a secondary target. On a hit with 0–1 Recoil, remove both and gain tokens for both. With 2+ Recoil, you may remove the secondary instead of the primary, gaining only its token.'),'escalation',8,s=>edge(s,'killshot')),
R('goodboy','turns','both',L('Good Boy: aliado oculto','Good Boy: hidden ally'),L('Uma vez por partida, imediatamente antes/depois de mover, o sniper solta o cão: marque G em espaço adjacente do mesmo tipo no tabuleiro oculto. Nos turnos seguintes, ele pode mover 1 espaço, alertando como movimento ruidoso; não diga quem fez o som. Observar/Varrer revela o cão, sem adicionar Ruído ao saco. No turno seguinte à revelação ele não pode mover. Não pode ser atacado.','Once per game, immediately before/after moving, the sniper releases the dog: mark G in a matching-adjacent space on the hidden board. On subsequent turns it may move 1 space, alerting as noisy movement; do not identify the source. Spot/Sweep reveals the dog, without adding Noise to the bag. It cannot move on the turn after being revealed. It cannot be attacked.'),'escalation',9,s=>edge(s,'goodboy')),
R('flares','turns','both',L('Flares: sinalizadores','Flares'),L('Após escolher especialistas, coloque 1 sinalizador em cada carta. Uma vez por turno dos defensores, sem ação, um oficial com sinalizador pode lançá-lo em espaço aberto visível a até 2 espaços. No início do turno do sniper, se ele está em espaço aberto a até 2 espaços do sinalizador, deve informar e adicionar 1 Recuo, sem dizer onde está. Depois, retire o sinalizador da partida, tenha afetado o sniper ou não.','After choosing specialists, put 1 flare on each card. Once per defender turn, without an action, an officer with a flare may fire it at a visible open space within 2 spaces. At the start of the sniper’s turn, if they are on an open space within 2 spaces of it, they must say so and add 1 Recoil, without revealing their exact position. Then remove the flare from the game whether or not it affected the sniper.'),'escalation',10,s=>edge(s,'flares')),
R('hunter','turns','both',L('Call the Hunter: quarto esquadrão','Call the Hunter: fourth squad'),L('Coloque Hunter, zona de entrada e cubo branco conforme o diagrama do mapa (p.18). É um esquadrão de 1 soldado com 1 ação por turno: Mover 2; Mover até 1 + Observar; Mover até 1 + Atacar o próprio espaço; Recolocar na zona; Dispensar. Não coleta informações. Outro esquadrão pode gastar suas duas ações, em vez de agir/investigar, para chamar o Hunter: ele faz imediatamente uma ação ainda não usada no turno. Tem blindagem 2: exige +2 Mira (mínimo 3). Avance também o cubo branco na contagem.','Place Hunter, deployment zone and white cube according to the map diagram (p.18). This is a one-soldier squad with 1 action per turn: Move 2; Move up to 1 & Spot; Move up to 1 & Attack its own space; Deploy at the zone; Dismiss. It cannot gather intel. Another squad may spend both its actions instead of acting/gathering intel to call the Hunter: it immediately takes an action not yet used this turn. Armour 2 requires +2 Aim (minimum 3). Advance its white countdown cube too.'),'escalation',11,s=>edge(s,'hunter')),
R('upgrades','turns','sniper',L('Equipamentos aprimorados','Upgraded loadouts'),L('Cada aprimoramento substitui 1 cópia da carta normal e ocupa um dos equipamentos iniciais; não aumenta a mão. Major Distraction dispensa visão e divide movimento entre dois alvos. Advanced Sound Masking: até 4 espaços com ruído ou até 3 em silêncio. Modified Tommy Gun adiciona temporariamente 2 Miras, retiradas após os tiros e antes das recompensas. Armour-piercing Rounds atravessa prédios e facilita acerto conforme a carta; não transforma Ruído em Recuo e dá 1 equipamento aleatório depois. Trip Mines afeta soldados adjacentes do mesmo tipo ao disparar. Bayonet volta à mão e permite outra carta, mas não outra Bayonet no turno. Panzerfaust pode mirar espaço adjacente. As páginas 12–13 descrevem as mudanças; consulte a carta física para os detalhes numéricos e de ativação que o manual não reproduz.','Each upgrade replaces 1 normal copy and occupies one starting loadout slot; it does not increase your hand. Major Distraction needs no sight and splits movement between two targets. Advanced Sound Masking: up to 4 spaces with noise or up to 3 silently. Modified Tommy Gun temporarily adds 2 Aim, removed after the shots and before rewards. Armour-piercing Rounds shoots through buildings and improves hits as printed; it does not convert Noise to Recoil and grants 1 random loadout afterward. Trip Mines affects matching-adjacent soldiers when triggered. Bayonet returns to hand and permits another card, but not another Bayonet that turn. Panzerfaust may target an adjacent space. Pages 12–13 describe the changes; consult the physical card for numeric and trigger details that the rulebook does not reproduce.'),'escalation',12,s=>s.upgrades>0),
R('elite','turns','defender',L('Especialistas de elite','Elite specialists'),L('Substitua o especialista normal correspondente. Passivas podem ser usadas todo turno mesmo após os 2 usos da habilidade, mas apenas com o oficial no tabuleiro. Sennenhund protege soldados de outros esquadrões adjacentes do mesmo tipo e tem blindagem 2. Spürhund permite ao soldado movido agir (não atacar); ao coletar informações, move uma unidade do esquadrão. Kobra ataca até 2 espaços com visão. Schakal pode mover antes da habilidade, impedindo ataque do soldado recolocado; dispensa unidades de qualquer esquadrão sem ação, sem recolocá-las naquele turno. Adler observa até 3 espaços com visão. Koyote coloca cães adjacentes do mesmo tipo; eles detectam movimento para/dentro/adjacente mesmo silencioso, e podem Mover/Varrer/Observar usando ações do esquadrão.','Replace the matching normal specialist. Passives work every turn even after both ability uses, but only while the officer is on the board. Sennenhund protects matching-adjacent soldiers from other squads and has armour 2. Spürhund allows the moved soldier to act (not attack); when gathering intel, move a squad unit. Kobra attacks within 2 spaces with sight. Schakal may move before his ability, preventing the deployed soldier from attacking; dismiss units of any squad without an action, with no same-turn redeployment. Adler spots within 3 spaces with sight. Koyote places dogs matching-adjacent; they detect movement into/through/adjacent even when silent, and may Move/Sweep/Spot using squad actions.'),'escalation',14,s=>s.elites>0),
R('schedule','turns','both',L('Accelerated Schedule: 7 turnos','Accelerated Schedule: 7 turns'),L('Comece e reinicie a contagem em 7 em vez de 10. O sniper tem apenas sete turnos para cada objetivo.','Start and reset the countdown at 7 instead of 10. The sniper has only seven turns for each objective.'),'escalation',16,s=>edge(s,'schedule')),
R('rapid','turns','both',L('Rapid Response','Rapid Response'),L('Após o primeiro objetivo do sniper, adicione 1 Ruído extra ao saco e restaure 1 uso de cada especialista. Não ultrapasse 2 cubos por carta.','After the sniper’s first objective, add 1 extra Noise to the bag and restore 1 use of each specialist. Do not exceed 2 cubes on a card.'),'escalation',16,s=>edge(s,'rapid')),
R('tipped','turns','both',L('Tipped Off','Tipped Off'),L('Após escolher especialistas, os defensores trancam quaisquer 2 portas durante a preparação.','After choosing specialists, defenders lock any 2 doors during setup.'),'escalation',16,s=>edge(s,'tipped')),
R('roadblocks','turns','both',L('Roadblocks','Roadblocks'),L('Coloque terreno difícil nas quatro entradas. Coloque a quinta ficha em um espaço aberto não adjacente a qualquer terreno difícil, inclusive o impresso e as entradas.','Place difficult terrain at all four entrances. Place the fifth token on an open space not adjacent to any difficult terrain, including printed terrain and the entrances.'),'escalation',17,s=>edge(s,'roadblocks')),
R('mechanisation','turns','both',L('Mechanisation','Mechanisation'),L('Use os veículos de Operation Kraken em Heavy Water. O diagrama da página 19 define as estradas e as posições iniciais; as demais regras dos veículos são as mesmas de Norman Village.','Use Operation Kraken vehicles on Heavy Water. The page 19 diagram defines roads and starting positions; other vehicle rules match Norman Village.'),'escalation',19,s=>edge(s,'mechanisation')),
R('curfew','turns','both',L('Under Curfew','Under Curfew'),L('Após escolher especialistas, coloque as 11 fichas de porta em portas do mapa, abertas. Unidades embarcadas não podem trancar/destrancar. Antes de escolher equipamentos, adicione Bolt Cutters ao baralho. Use as regras de portas de Super Carrier.','After choosing specialists, place the 11 door tokens on map doorways, unlocked. Embarked units cannot lock/unlock. Before choosing loadout, add Bolt Cutters to the deck. Use Super Carrier door rules.'),'escalation',17,s=>edge(s,'curfew')),
R('sentries','turns','both',L('Sentries','Sentries'),L('No segundo turno dos defensores, o sniper deve dizer por qual entrada começou. Seus objetivos continuam fora do setor de entrada.','On the defenders’ second turn, the sniper must disclose their starting entrance. Their objectives are still outside the entry sector.'),'escalation',17,s=>edge(s,'sentries')),
];
export const equipment=[
{ name:'Sound Masking',book:'core',page:15,body:L('Neste turno, mover 2–3 espaços não alerta defensores. Revele ao fim da partida.','Moving 2–3 spaces does not alert defenders this turn. Reveal at game end.')},
{name:'S-Mine',book:'core',page:15,body:L('Marque X secretamente no seu espaço. Quando uma unidade inimiga terminar movimento ali, revele, mate-a e apague X.','Secretly mark X in your space. When an enemy unit ends movement there, reveal, kill it and erase X.')},
{name:'Silenced Ammo',book:'core',page:15,body:L('Revele antes de atirar. Neste turno, Ruído conta como Recuo: não revela posição, mas 5+ ainda causa falha.','Reveal before shooting. This turn Noise counts as Recoil: it does not reveal position, but 5+ still causes a misfire.')},
{name:'Distraction',book:'core',page:15,body:L('Mova uma unidade inimiga até 2 espaços. Ela deve terminar em sua linha de visão. Revele antes de usar.','Move an enemy unit up to 2 spaces. It must end in your line of sight. Reveal before use.')},
{name:'Tommy Gun',book:'core',page:15,body:L('Atire uma vez extra. Anuncie quantas fichas comprará em cada tiro antes do primeiro. Não devolva as primeiras fichas antes do segundo; resolva o Ruído de todos os tokens depois do segundo tiro. Revele antes de atirar.','Shoot one extra time. Announce the token count for each shot before the first. Do not return the first draw before the second; resolve Noise from all tokens after the second shot. Reveal before shooting.')},
{name:'Trench Gun',book:'core',page:15,body:L('Ao atirar, não compre fichas. Revele sua posição e mate todas as unidades inimigas no seu espaço e nos adjacentes do mesmo tipo. Não adicione fichas ao saco. Revele antes de atirar.','When shooting, draw no tokens. Reveal your position and kill all enemy units in your space and matching-adjacent spaces. Add no tokens to the bag. Reveal before shooting.')},
{name:'Knife',book:'eagle',page:8,when:s=>s.expansions.includes('eagle')&&s.eagleLoadout,body:L('Revele posição e mate um defensor no seu espaço; +1 Mira ao saco. Ainda pode mover e agir neste turno. Revele antes de usar.','Reveal position and kill a defender in your space; +1 Aim to the bag. You may still move and take an action this turn. Reveal before use.')},
{name:'Diving Gear',book:'eagle',page:8,when:s=>s.expansions.includes('eagle')&&s.eagleLoadout&&['launch','pens','water'].includes(s.map),body:L('Pode mover através de água neste turno, mas não terminar nela. Abdique de todas as ações que não sejam movimento. Defensores adjacentes ouvem normalmente. Revele ao fim da partida.','Move through water this turn, but do not end there. Forfeit all non-movement actions. Adjacent defenders hear normally. Reveal at game end.')},
{name:'Climbing Gear',book:'eagle',page:8,when:s=>s.expansions.includes('eagle')&&s.eagleLoadout&&['pens','water'].includes(s.map),body:L('Se mover apenas 1 espaço neste turno, pode cruzar entre elevado e aberto sem acesso. Não funciona movendo 2–3. Revele ao fim da partida.','If moving only 1 space this turn, cross between elevated and open without an access point. Does not work when moving 2–3. Reveal at game end.')},
{name:'Explosive Entrance',book:'kraken',page:3,when:s=>s.map==='carrier',body:L('Revele sua posição. Coloque a ficha numa parede do seu espaço: pelo resto da partida ela é uma porta entre os dois espaços. Usa sua ação. Revele antes de usar.','Reveal your location. Put the token on a wall bordering your space: for the rest of the game it is a doorway between those spaces. This uses your action. Reveal before use.')},
{name:'Bolt Cutters',book:'kraken',page:3,when:s=>s.map==='carrier'||edge(s,'curfew'),body:L('Circule secretamente uma porta trancada no seu espaço. Pode atravessá-la, mesmo trancada, até a carta ser revelada. Quando inimigo destrancar essa porta, revele a carta e risque o círculo; depois disso a porta funciona normalmente.','Secretly circle a locked door in your space. You can pass through it, even locked, until this card is revealed. When an enemy unlocks it, reveal the card and cross out the circle; the door then works normally.')}
];
export function setup(s){const m=maps.find(m=>m.id===s.map),out=[];const add=(id,title,body,book='core',page=4)=>out.push({id,title,body,book,page});
if(s.expansions.includes('escalation'))add('ops',L('Definir a Special Op','Define the Special Op'),L(`Patente ${['','Private','Corporal','Sergeant'][s.rank]}: ${s.rank} vantagem(ns) para cada lado. ${['launch','pens','water'].includes(s.map)?'Sniper escolhe primeiro':'Defensores escolhem primeiro'}. Missões e vantagens são públicas imediatamente. Anuncie só quantidades de equipamentos aprimorados/extras e especialistas de elite; escolha as cartas na etapa normal.`,`Rank ${['','Private','Corporal','Sergeant'][s.rank]}: ${s.rank} edge(s) per side. ${['launch','pens','water'].includes(s.map)?'Sniper chooses first':'Defenders choose first'}. Missions and advantages are public immediately. Announce only counts for upgraded/extra loadouts and elite specialists; choose the cards at their normal setup step.`),'escalation',6);
add('board',L('Preparar o mapa','Prepare the map'),L(`Use ${m.name}, o tabuleiro oculto correspondente e suas 9 cartas de objetivo. Entregue marcador, miniatura, saco e equipamentos ao sniper. Aos defensores: unidades, cubos, Supressões e marcador de ferimento.`, `Use ${m.name}, its hidden board and its 9 objective cards. Give the sniper marker, miniature, shot bag and loadouts. Give defenders units, cubes, Suppression and wound token.`));
add('targets',L('Sortear objetivos em segredo','Draw secret objectives'),L(s.map==='carrier'?'Compre 2 cartas com naipes E valores diferentes; devolva uma ao fundo e compre outra até cumprir ambos. Use a única entrada do navio.':'Compre 2 cartas com naipes diferentes; se iguais, devolva uma à escolha ao fundo e repita. No primeiro turno, escolha uma entrada em setor sem nenhum desses objetivos.',s.map==='carrier'?'Draw 2 cards with different suits AND values; return one to the bottom and redraw until both differ. Use the ship’s single entrance.':'Draw 2 cards with different suits; if equal, return one of your choice to the bottom and repeat. On your first turn, choose an entrance in a sector containing neither objective.'),s.map==='carrier'?'kraken':'core',s.map==='carrier'?6:4);
const bag=snipers[s.allied].bag;
add('bag-setup',L('Preparar o saco de tiro','Prepare the shot bag'),L(bag?`${snipers[s.allied].name}: ${bag[0]} Mira, ${bag[1]} Ruído e ${bag[2]} Recuo. Misture bem; reserve as demais fichas permitidas. Aliado escolhido fica visível.`:'Ghost Sniper: sorteie um aliado secretamente e use a composição da carta. Mantenha carta, saco e reserva ocultos.',bag?`${snipers[s.allied].name}: ${bag[0]} Aim, ${bag[1]} Noise and ${bag[2]} Recoil. Mix thoroughly; set aside the remaining permitted tokens. A chosen ally is public.`:'Ghost Sniper: secretly draw an ally and use its printed bag composition. Hide the card, bag and supply.'),s.allied==='base'?'core':'eagle',s.allied==='base'?4:3);
add('gear',L('Montar baralho e escolher equipamentos','Build the deck and choose loadout'),L(`Escolha ${3+s.extras} cartas em segredo, depois embaralhe o restante. ${s.upgrades?`${s.upgrades} delas são aprimoradas; remova uma cópia normal por aprimoramento.`:''} ${s.expansions.includes('eagle')&&s.eagleLoadout?'Inclua os equipamentos Eagle’s Nest compatíveis: retire Climbing Gear sem elevados e Diving Gear sem água.':''} ${s.map==='carrier'?'Inclua Explosive Entrance e Bolt Cutters.':edge(s,'curfew')?'Inclua Bolt Cutters.':''} Escolha antes dos especialistas.`,`Secretly choose ${3+s.extras} cards, then shuffle the rest. ${s.upgrades?`${s.upgrades} are upgrades; remove one normal copy per upgrade.`:''} ${s.expansions.includes('eagle')&&s.eagleLoadout?'Include compatible Eagle’s Nest gear: remove Climbing Gear without elevated spaces and Diving Gear without water.':''} ${s.map==='carrier'?'Include Explosive Entrance and Bolt Cutters.':edge(s,'curfew')?'Include Bolt Cutters.':''} Choose before specialists.`));
add('units',L('Posicionar defensores','Place defenders'),L('Coloque os 6 soldados e 3 oficiais nos círculos da própria cor; oficiais nos símbolos de cruz. Há sempre 3 esquadrões: com 1 defensor, ele controla todos; com 2, cada um controla um e compartilham o terceiro; com 3, um esquadrão para cada.','Place 6 soldiers and 3 officers on matching coloured circles; officers use cross symbols. Always use 3 squads: 1 defender controls all; 2 control one each and share the third; 3 control one squad each.'));
add('officers',L('Escolher especialistas','Choose specialists'),L(`Escolha 3 especialistas públicos${s.elites?`, sendo ${s.elites} de elite, substituindo suas versões normais`:''}. Atribua um a cada esquadrão com 2 cubos da cor e 1 Supressão por carta. Use os 2 cães apenas se houver Kennel Master/Koyote.`,`Choose 3 public specialists${s.elites?`, including ${s.elites} elite cards replacing their normal versions`:''}. Assign one per squad with 2 matching cubes and 1 Suppression per card. Use the 2 dogs only with Kennel Master/Koyote.`));
if(vehicles(s))add('cars',L('Posicionar veículos','Place vehicles'),L('Coloque os 2 veículos nos símbolos iniciais e suas 2 cartas visíveis. Em Heavy Water, use o diagrama de Mechanisation da página 19.','Place 2 vehicles at their start icons and both cards face up. On Heavy Water, use the Mechanisation diagram on page 19.'),edge(s,'mechanisation')?'escalation':'kraken',edge(s,'mechanisation')?19:4);
if(doors(s))add('door-setup',L('Preparar portas','Prepare doors'),L(s.map==='carrier'?'Coloque as 11 fichas nas portas indicadas, abertas.':'Após especialistas, coloque 11 fichas em portas do mapa, abertas. Adicione Bolt Cutters antes de escolher equipamentos.',s.map==='carrier'?'Place the 11 tokens on marked doorways, unlocked.':'After specialists, place 11 tokens on map doorways, unlocked. Add Bolt Cutters before choosing loadout.'),'kraken',6);
for(const id of ['goodboy','flares','hunter','tipped','roadblocks'])if(edge(s,id)){const r=rules.find(r=>r.id===id);add('setup-'+id,r.title,r.body,r.book,r.page);}
add('clock',L('Contagem e primeiro turno','Countdown and first turn'),L(`Coloque os 6 cubos restantes no ${limit(s)}, e o ferimento no lado intacto.${edge(s,'hunter')?' Coloque também o cubo branco na mesma casa.':''} O sniper joga primeiro; depois os defensores, alternadamente.`,`Put the 6 remaining cubes on ${limit(s)}, and the wound token on its full side.${edge(s,'hunter')?' Put the white cube on the same space too.':''} The sniper plays first, then the defenders; alternate.`));return out.map(r=>{let sources=[r.book];if(r.id==='board'&&m.box!=='core')sources.push(m.box);if(r.id==='gear'){if(s.expansions.includes('eagle')&&s.eagleLoadout)sources.push('eagle');if(s.map==='carrier'||edge(s,'curfew'))sources.push('kraken');if(s.upgrades||s.extras)sources.push('escalation');}if((r.id==='officers'&&s.elites)||(r.id==='clock'&&(edge(s,'schedule')||edge(s,'hunter'))))sources.push('escalation');return {...r,sources:[...new Set(sources)]};});}
export function components(s) {
 const m=maps.find(m=>m.id===s.map), a=[];
 const add=(id,book,pt,en)=>a.push({id,book,body:L(pt,en)});
 add('map',m.box,'1 tabuleiro principal do mapa selecionado\n1 tabuleiro oculto correspondente\n9 cartas de objetivo do mapa','1 main board for the selected map\n1 matching hidden board\n9 objective cards for the map');
 add('sniper','core','1 miniatura de sniper\n1 marcador apagável\n1 saco de tiro','1 sniper miniature\n1 dry-erase marker\n1 shot bag');
 add('tokens','core','11 fichas de Mira\n9 fichas de Ruído\n3 fichas de Supressão\nFichas de Recuo conforme o sniper escolhido','11 Aim tokens\n9 Noise tokens\n3 Suppression tokens\nRecoil tokens according to the chosen sniper');
 add('units','core','6 soldados\n3 oficiais\n9 bases\n12 cubos de ação\n10 cubos de rastreamento','6 soldiers\n3 officers\n9 bases\n12 action cubes\n10 tracking cubes');
 add('aids','core','1 trilha de contagem\n1 marcador de ferimento\n3 cartas de especialista escolhidas\n2 cartas de referência','1 countdown track\n1 wound token\n3 chosen specialist cards\n2 player aids');
 add('loadout','core','10 equipamentos básicos\n2 cães, apenas com Kennel Master ou Koyote','10 base loadout cards\n2 dogs, only with Kennel Master or Koyote');
 if(s.expansions.includes('eagle')&&s.eagleLoadout){let pt=['2 Knife'],en=['2 Knife'];if(['launch','pens','water'].includes(s.map)){pt.push('2 Diving Gear');en.push('2 Diving Gear');}if(['pens','water'].includes(s.map)){pt.push('2 Climbing Gear');en.push('2 Climbing Gear');}add('eagle-gear','eagle',pt.join('\n'),en.join('\n'));}
 if(s.allied!=='base')add('ally','eagle','Carta do aliado selecionado\nMiniatura correspondente\nGhost: sorteie entre as 4 cartas em segredo','Chosen ally card\nMatching miniature\nGhost: secretly draw from the 4 cards');
 if(vehicles(s))add('vehicles','kraken','2 miniaturas de veículo\n2 cartas de veículo','2 vehicle miniatures\n2 vehicle cards');
 if(doors(s))add('doors','kraken','11 fichas de porta','11 door tokens');
 if(s.map==='carrier')add('carrier-gear','kraken','1 ficha Explosive Entrance\n1 carta Explosive Entrance\n1 carta Bolt Cutters','1 Explosive Entrance token\n1 Explosive Entrance card\n1 Bolt Cutters card');
 if(edge(s,'curfew'))add('cutters','kraken','1 carta Bolt Cutters','1 Bolt Cutters card');
 if(s.expansions.includes('escalation'))add('edges','escalation','Cartas de missão escolhidas\nCartas de vantagem escolhidas\nEquipamentos aprimorados escolhidos\nEspecialistas de elite escolhidos','Selected mission cards\nSelected advantage cards\nSelected upgraded loadouts\nSelected elite specialists');
 if(edge(s,'goodboy'))add('dog','escalation','1 miniatura Good Boy','1 Good Boy miniature');
 if(edge(s,'flares'))add('flares','escalation','3 sinalizadores\nFichas extras de Recuo na reserva','3 flare tokens\nExtra Recoil tokens in the supply');
 if(edge(s,'hunter'))add('hunter','escalation','1 miniatura Hunter\n1 base branca\n1 cubo branco\n1 ficha de zona de entrada','1 Hunter miniature\n1 white base\n1 white cube\n1 deployment zone token');
 if(edge(s,'roadblocks'))add('terrain','escalation','5 fichas de terreno difícil','5 difficult terrain tokens');
 return a;
}

const E=(id,title,body,book,page,when)=>({id,title,body,book,page,when});
