E('loadout-example',L('Três vantagens, cinco equipamentos','Three edges, five loadouts'),L('Com 3 vantagens: 2 equipamentos extras + 1 aprimoramento resultam em 5 cartas iniciais, uma delas aprimorada. Aprimorar não adiciona uma carta extra.','With 3 edges: 2 extra loadouts + 1 upgrade give 5 starting cards, one upgraded. An upgrade does not add an extra card.'),'escalation',13,s=>s.expansions.includes('escalation'))
