export const actionIds={sniper:['shoot','loot','objective'],defender:['defender-move','attack','spot','sweep','deploy-officer','deploy-soldier','dismiss']};
rules.push(
 R('deploy-officer','turns','defender',L('Recolocar oficial','Deploy officer'),L('O oficial deve estar fora do tabuleiro. Coloque-o no espaço inicial da sua cor. Se outro defensor ocupar o espaço, mova-o antes. O sniper oculto não impede a recolocação.','The officer must be off the board. Place them on their colour’s starting space. If another defender occupies it, move that unit first. A hidden sniper does not prevent deployment.'),'core',9),
 R('deploy-soldier','turns','defender',L('Recolocar soldado','Deploy soldier'),L('O soldado deve estar fora do tabuleiro. Seu oficial deve estar no próprio setor. Coloque o soldado em espaço adjacente do mesmo tipo ao oficial. O espaço pode estar em outro setor. Esta ação pertence ao soldado, não ao oficial. O soldado ainda pode fazer outra ação diferente, se houver ação disponível no esquadrão.','The soldier must be off the board. Their officer must be in their own sector. Place the soldier in a matching-adjacent space to that officer. The space may be in another sector. This is the soldier’s action, not the officer’s. The soldier may still take a different action if the squad has one remaining.'),'core',9),
 R('dismiss','turns','defender',L('Dispensar unidade','Dismiss unit'),L('Retire um soldado ou oficial deste esquadrão do tabuleiro. Essa unidade não pode ser recolocada no mesmo turno.','Remove a soldier or officer from this squad from the board. That unit cannot redeploy this turn.'),'core',9)
);
export function instructionLines(value){return String(value).split(/\n+|;\s*|[.]\s+(?=[A-ZÀ-Ý0-9“])/u).map(x=>x.trim()).filter(Boolean);}
export function turnGroups(s){
 const allowed=rules.filter(r=>applies(r,s)&&(r.role==='both'||r.role===s.role)&&r.id!=='deploy');
 const groups=s.role==='defender'?[
 ['overview',L('Como funciona o turno','How the turn works'),['defender-turn']],
 ['alternative',L('Alternativa às duas ações','Alternative to both actions'),['intel','carrier-intel']],
 ['actions',L('Ações disponíveis','Available actions'),actionIds.defender],
 ['abilities',L('Habilidades e ações da expansão','Abilities and expansion actions'),['specialists','elite','vehicle','hunter','flares']],
 ]:[
 ['overview',L('Como funciona o turno','How the turn works'),['sniper-turn']],
 ['movement',L('Movimento e equipamento','Movement and loadout'),['movement','loadout']],
 ['actions',L('Escolha uma ação adicional','Choose one additional action'),actionIds.sniper],
 ];
 const used=new Set(groups.flatMap(g=>g[2]));
 return [...groups.map(([id,title,ids])=>({id,title,rules:ids.map(id=>allowed.find(r=>r.id===id)).filter(Boolean)})),{id:'reference',title:L('Regras de apoio e exceções','Supporting rules and exceptions'),rules:allowed.filter(r=>!used.has(r.id))}].filter(g=>g.rules.length);
}
